class LatencyMetric(BaseMetric):
    def __init__(self, max_ms: float = {{max_ms}}, threshold: float = {{threshold}}):
        self.threshold = threshold
        self.max_ms = max_ms
        self.evaluation_model = "latency-checker"

    def measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        latency = test_case.completion_time or 0
        latency_ms = latency * 1000
        if latency_ms >= self.max_ms:
            self.score = 0.0
            self.reason = f"响应时间 {latency_ms:.0f}ms 超过上限 {self.max_ms:.0f}ms"
        else:
            self.score = round(1.0 - (latency_ms / self.max_ms), 3)
            self.reason = f"响应时间 {latency_ms:.0f}ms，得分 {self.score}"
        self.success = self.score >= self.threshold
        return self.score

    async def a_measure(self, test_case: LLMTestCase, *args, **kwargs) -> float:
        return self.measure(test_case)

    def is_successful(self) -> bool:
        return bool(self.score and self.score >= self.threshold)

    @property
    def __name__(self):
        return "Latency Check"
